import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  ElementRef,
  contentChild,
  effect,
  inject,
  input,
  model,
} from '@angular/core';

@Directive({ selector: '[aevkoTooltipTrigger]', standalone: true })
export class AevkoTooltipTrigger {
  readonly element = inject<ElementRef<HTMLElement>>(ElementRef);
}

@Component({
  selector: 'aevko-tooltip',
  standalone: true,
  templateUrl: './tooltip.component.html',
  styleUrl: './tooltip.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '(mouseenter)': 'schedule(true)',
    '(mouseleave)': 'schedule(false)',
    '(focusin)': 'schedule(true)',
    '(focusout)': 'schedule(false)',
    '(keydown.escape)': 'open.set(false)',
  },
})
export class AevkoTooltip {
  readonly id = input('aevko-tooltip');
  readonly open = model(false);
  readonly side = input<'top' | 'right' | 'bottom' | 'left'>('top');
  readonly delay = input(300);
  private readonly trigger = contentChild(AevkoTooltipTrigger);
  private timer?: ReturnType<typeof setTimeout>;
  constructor() {
    effect(() => {
      const element = this.trigger()?.element.nativeElement;
      if (!element) return;
      element.setAttribute('aria-describedby', this.id());
    });
  }
  protected schedule(value: boolean): void {
    clearTimeout(this.timer);
    this.timer = setTimeout(() => this.open.set(value), value ? this.delay() : 0);
  }
}

:host {
  display: inline-block;
  position: relative;
}
span {
  background: var(--aevko-foreground, #171717);
  border-radius: 0;
  color: var(--aevko-background, #fff);
  font-size: 0.75rem;
  inline-size: max-content;
  max-inline-size: 16rem;
  padding: 0.375rem 0.625rem;
  pointer-events: none;
  position: absolute;
  z-index: 40;
}
span[data-side='top'] {
  inset-block-end: calc(100% + 0.375rem);
  inset-inline-start: 50%;
  transform: translateX(-50%);
}
span[data-side='bottom'] {
  inset-block-start: calc(100% + 0.375rem);
  inset-inline-start: 50%;
  transform: translateX(-50%);
}
span[data-side='left'] {
  inset-inline-end: calc(100% + 0.375rem);
  inset-block-start: 50%;
  transform: translateY(-50%);
}
span[data-side='right'] {
  inset-inline-start: calc(100% + 0.375rem);
  inset-block-start: 50%;
  transform: translateY(-50%);
}
@media (prefers-color-scheme: dark) {
  span {
    --aevko-foreground: #f5f5f5;
    --aevko-background: #171717;
  }
}
